class Garage {
  private free: number[];
  constructor(large: number, medium: number, small: number) {
    this.free = [0, large, medium, small]; // index 0 unused so free[size] works
  }

  park(size: number): boolean {
    if (this.free[size] === 0) return false;
    this.free[size]--;
    return true;
  }
}

